  setDecisionError("");
  if(adminDecision==="move"&&student.notes&&!effectiveInfoStatus){setError("Classifica a informação ou seleciona Validar posteriormente antes de guardar.");return}
  if(detailsChanged&&manualChanged){setError("Alteraste os dados-base e o destino deste rascunho ao mesmo tempo. Guarda primeiro os dados-base; os rascunhos serão recalculados e depois poderás ajustar o destino no cenário escolhido.");return}
  if(manualRequiresImbalanceException&&!imbalanceConfirmed){setError(`Esta mudança aumenta a diferença global de ${manualBeforeDifference} para ${manualAfterDifference}. Confirma a exceção de equilíbrio antes de guardar.`);return}
